import Colors from '@dynatrace/strato-design-tokens/colors';

import { HoneycombTileMetaData } from '../types/honeycomb-internal.js';
import { HoneycombTileData } from '../types/honeycomb.js';
import { TileColorMetadata } from '../types/rendering.js';

export const getMetadataMap = (
  data: HoneycombTileData[],
  colorBasedOnData: WeakMap<HoneycombTileData, TileColorMetadata>,
) => {
  const metadataMap = new WeakMap<HoneycombTileData, HoneycombTileMetaData>();
  data.forEach((item, idx) => {
    const stringColor =
      colorBasedOnData.get(item)?.baseColor ??
      Colors.Charts.Categorical.Color05.Default;
    const tokenColor = { Default: stringColor };
    metadataMap.set(item, {
      id: `${item.name ?? 'unknown'}-${idx}`,
      ...item,
      name: item.name ?? '',
      color: tokenColor,
    });
  });
  return metadataMap;
};
